import{z as A,x as B,o as E,c as d,q as o,j as t,D as i,d as r,s as l,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"Midtraining","description":"","frontmatter":{"title":"Midtraining","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/midtraining.md","filePath":"llm/midtraining.md","lastUpdated":1791063341000}'),p={name:"llm/midtraining.md"};function m(g,a,F,h,P,D){const e=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=o('<h1 id="midtraining" tabindex="-1">Midtraining <a class="header-anchor" href="#midtraining" aria-label="Permalink to &quot;Midtraining&quot;">​</a></h1><div class="epigraph"><p>预训练的后 5%–10% FLOPs 不再当成同一锅网页汤：换成更高质量、补短板、或拉长上下文的混合，并常常伴随学习率退火。这是课程阶段，不是另一次从零预训练。</p><footer>—— OLMo Team 采用 Abdin et al. 与 OpenAI 2024 的 mid-training 说法，见 *2 OLMo 2 Furious*，arXiv:2501.00656；长上下文实例见 Abdin 等 Phi-4，arXiv:2412.08905</footer></div><p>经典配方是「大规模预训练 → 指令微调」。近年底座在接 SFT 之前多出一段 <strong>midtraining（中训）</strong>：数据更干净或更偏领域，学习率从预训练峰值降下来，有时把窗口从 4K 拉到 16K / 32K。OLMo 2 把第二阶段明确叫做 mid-training，约占训练 FLOPs 的 5%–10%，用 Dolmino Mix 上采样优质网页、非网页源与补数学的合成数据，并用 micro-annealing 先试数据源再决定是否进入正式退火。Phi-4 的中训把上下文从 4K 接到 16K，约 250B token，长数据约占 30%、预训练回放约 70%，RoPE 基频提到 250K，学习率降到预训练峰值的十分之一。名称来自 Phi-3.5 / Phi-4 与 OpenAI 2024 的用法；谱系上接近 Gururangan 等「不要停预训练」的领域自适应，但对象是通用底座的课程，而不是单一下游语料。本篇把 midtraining 写成<strong>阶段</strong>，不把退火学习率、长上下文延伸、合成补丁当成三篇论文的同一公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>万亿级网页预训练边际递减：噪声 token 仍占步数，短板（数学、多语、长依赖）在均匀混合里得不到足够密度。若把高质量数据从第一步就灌满，模型还没学到宽覆盖的表面统计，就过拟合窄域。若全部留给 SFT，监督信号太稀，补不回底座缺口。中训插在两者之间：骨干已会语言，再用短而密的阶段打补丁，并常把优化器从「高原」转入余弦尾部。</p><p><span class="marginnote">直觉类比：预训练像九年义务教育什么都学一点，中训像高三冲刺——内容更精、更难，但仍是同一个人在成长，不是换专业重修；SFT 才是上岗培训。阶段顺序错了（先窄后宽），窄域会过拟合。</span></p><p>第二个问题是实验成本。为试一种数学混合而重跑 5T 不可行。OLMo 2 的 micro-annealing 用小规模退火评估数据源，把「这一锅值不值得」从完整重训里拆出来。长上下文同理：Phi-4 消融发现<strong>天然长文档</strong>优于把短样本 pad 成假长序列；于是中训的数据工程是筛 &gt;8K、上采样 ≥16K，而不是只改 RoPE。</p><h3 id="名称混用-退火、续训、中训" tabindex="-1">名称混用：退火、续训、中训 <a class="header-anchor" href="#名称混用-退火、续训、中训" aria-label="Permalink to &quot;名称混用：退火、续训、中训&quot;">​</a></h3><p>Annealing 多指学习率降到零的日程尾部，数据可以不变。Continued pretraining 常指在新领域上接着训（Gururangan 2020）。Midtraining 在 OLMo 2 / Phi 里同时改<strong>数据混合与日程</strong>，有时还改<strong>窗口</strong>。三者可重叠：OLMo 2 的第二阶段就是带新混合的退火。写报告应拆开：改了哪些分布、LR 峰值降了几倍、上下文是否变、占多少 FLOPs。</p><p><span class="marginnote">OLMo 2 脚注写明术语取自 Abdin et al. 2024a 与 OpenAI 2024。不要把 2020 年领域续训论文改名为 midtraining，也不要给 OpenAI 未公开的内部混合编造配比。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>典型三件套，可只做子集。</p><p><strong>数据。</strong> 提高高质量网页、书、代码、学术的密度；加入合成推理或指令风格（仍是下一 token，不是 SFT 对话格式——若已经是对话，阶段界线就挪到后训练）。OLMo 2：Dolmino Mix 1124，含合成数学以补短板。Phi-4：长上下文子集 + 70% 回放以防遗忘。回放比例是遗忘与新能力的旋钮。</p><p><span class="marginnote">Phi-4 的 70/30 配比可以这样读：中训每 10 个 token 里只有 3 个是新的长文本，另外 7 个在「复习旧课」。复习少了，学长的过程会把短任务的本领冲掉——这是数据层面的遗忘对策。</span></p><p><strong>优化。</strong> 峰值学习率降一档（Phi-4 为 10×），余弦或线性收到 0。权重衰减与全局 batch 可保持，但 token/step 若因更长窗口变，等效噪声尺度会变。不要沿用预训练 warmup。</p><p><strong>窗口。</strong> 中训是目前最常见的「4K→16K」放置处：先在短窗把容量训满，再在较短 token 预算上教长依赖。Phi-4 跟随 Meta 把 RoPE 基频提到 250K；OLMo 2 主报告默认仍 4K，长窗是另一条线，不要写成 OLMo 2 已经 16K 中训。</p><h3 id="与后训练的接口" tabindex="-1">与后训练的接口 <a class="header-anchor" href="#与后训练的接口" aria-label="Permalink to &quot;与后训练的接口&quot;">​</a></h3><p>中训结束的检查点仍是基座：没有聊天模板保证。OLMo 2 再接 Tulu 3 式 SFT → DPO → RLVR。Phi-4 再接 SFT 与偏好。若把指令数据提前灌进中训，能减轻 SFT 负担，也可能污染基座评测（MMLU 涨、续写风格变助理腔）。是否允许，属于配方，应在数据卡声明。PRISM 一类后续工作把中训与 RL 的交互单独拿出来测，说明界线仍在研究中。</p>',18)),(E(),t(s,null,{default:i(()=>[l(e,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20LR%0A%20%20PT%5B%22%E9%A2%84%E8%AE%AD%E7%BB%83%EF%BC%9A%E5%AE%BD%E8%A6%86%E7%9B%96%E7%BD%91%E9%A1%B5%20%E2%89%B390%25%20FLOPs%22%5D%20--%3E%20MT%5B%22%E4%B8%AD%E8%AE%AD%EF%BC%9A%E4%BC%98%E8%B4%A8%E6%B7%B7%E5%90%88%20%2F%20%E8%A1%A5%E7%9F%AD%E6%9D%BF%20%2F%20%E5%8F%AF%E9%80%89%E6%8B%89%E9%95%BF%E7%AA%97%E5%8F%A3%22%5D%0A%20%20MT%20--%3E%20SFT%5B%22SFT%22%5D%0A%20%20SFT%20--%3E%20PREF%5B%22%E5%81%8F%E5%A5%BD%20%2F%20RL%22%5D%0A%20%20LR%5B%22%E5%AD%A6%E4%B9%A0%E7%8E%87%E9%80%80%E7%81%AB%22%5D%20--%3E%20MT%0A%20%20REP%5B%22%E5%9B%9E%E6%94%BE%E9%A2%84%E8%AE%AD%E7%BB%83%20token%22%5D%20--%3E%20MT%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"评测要在中训前后用同一套基座任务（OLMES、学业多选、数学）。只报 SFT 后分数，无法知道补丁发生在中训还是指令阶段。长上下文任务必须用天然长评测，不能用拼接短文当成功标准——与 Phi-4 的训练消融同一逻辑。",-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[r("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,"课程学习把非平稳分布排成先易后难或先宽后窄。中训是「先宽覆盖、后高信噪」。信息瓶颈看法：前期学表层共现，后期用干净数据挤掉噪声方向。梯度噪声尺度随数据质量变：同样 batch，干净数据的梯度更对齐，可以用更小学习率走到更低损失而不抖。长窗口中训则是把注意力与 RoPE 的可行长度从「从未见过」变成「见过 30% 真长样本」；70% 短回放防止短任务灾难遗忘。",-1)),(E(),t(s,null,{default:i(()=>[l(e,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E9%95%BF%E7%AA%97%E5%8F%A3%E4%B8%AD%E8%AE%AD%E6%80%8E%E4%B9%88%E9%85%8D%E6%95%B0%E6%8D%AE%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%8F%AA%E5%96%82%E9%95%BF%E6%A0%B7%E6%9C%AC%22%7C%20F%5B%22%E7%9F%AD%E4%BB%BB%E5%8A%A1%E7%81%BE%E9%9A%BE%E9%81%97%E5%BF%98%22%5D%0A%20%20Q%20--%3E%7C%22%E5%8F%AA%E6%94%B9%20RoPE%20%E4%B8%8D%E5%96%82%E9%95%BF%22%7C%20X%5B%22%E5%8F%AA%E6%98%AF%E4%BD%8D%E7%BD%AE%E5%A4%96%E6%8E%A8%EF%BC%8C%E9%95%BF%E4%BE%9D%E8%B5%96%E6%B2%A1%E5%AD%A6%E4%BC%9A%22%5D%0A%20%20Q%20--%3E%7C%2230%25%20%E5%A4%A9%E7%84%B6%E9%95%BF%20%2B%2070%25%20%E5%9B%9E%E6%94%BE%22%7C%20G%5B%22%E9%95%BF%E4%BE%9D%E8%B5%96%E4%B9%A0%E5%BE%97%E4%B8%94%E7%9F%AD%E4%BB%BB%E5%8A%A1%E4%BF%9D%E4%BD%8F%22%5D%0A%20%20G%20--%3E%20E%5B%22%E7%94%A8%E5%A4%A9%E7%84%B6%E9%95%BF%E8%AF%84%E6%B5%8B%E9%AA%8C%E8%AF%81%EF%BC%8C%E4%B8%8D%E7%94%A8%E6%8B%BC%E6%8E%A5%E7%9F%AD%E6%96%87%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">常见误区：把「退火」和「中训」当成一回事。退火只动学习率日程，数据可以不变；中训同时改数据混合（常伴退火），有时还改窗口。读报告要拆开问：动了哪几样、各占多少 FLOPs。</span></p><p><span class="marginnote">Blakeney 等 2024、Ibrahim 等 2024 讨论预训练数据课程；Llama 3、DBRX、OLMo-0424 已展示分阶段混合。Midtraining 把「最后一段课程」命名并常与退火绑定，不是 2024 年才发明分阶段。</span></p><h3 id="和-sft-遗忘、和只拉长-rope" tabindex="-1">和 SFT 遗忘、和只拉长 RoPE <a class="header-anchor" href="#和-sft-遗忘、和只拉长-rope" aria-label="Permalink to &quot;和 SFT 遗忘、和只拉长 RoPE&quot;">​</a></h3><p>SFT 遗忘是监督分布替换无监督续写。中训仍是无监督（或弱监督合成），对基座任务通常更温和。只改 RoPE 基频、不喂长数据，是位置外推，不是中训。只喂长数据、不回放，短任务会掉——Phi-4 与 ProLong 都强调短长混合。合成长 QA 可作增强，不能替代天然长书与仓库级代码（Phi-4 消融）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>FLOPs 占比 5%–10% 是 OLMo 2 的叙述，不是定理。过短则补丁贴不上，过长则退化成「第二段预训练」且遗忘风险上升。数据许可证：中训若混入更严的来源，会收紧整个底座的再分发条件。micro-annealing 的小规模结论在满预算上可能反转，只能降实验成本，不能替代最终一次。</p><p>不要把 midtraining 写成视觉或 MoE 专有。不要给未公开的 GPT 中训写配比。窗口与 RoPE 必须和推理配置一致：中训 16K、服务 128K 仍要另做延伸。检查点选择：中训末与退火零点可能不是同一文件；下游应用以报告指定的 Base 为准。</p><p><span class="marginnote">出处：OLMo Team, <em>2 OLMo 2 Furious</em>，arXiv:2501.00656；Abdin et al., Phi-4 Technical Report，arXiv:2412.08905；Phi-3.5 对多语与长上下文中训的用法；Gururangan et al., Don&#39;t Stop Pretraining, 2020；综述：<em>Mid-Training of Large Language Models: A Survey</em>，arXiv:2510.06826。OpenAI 2024 仅作为术语来源引用，不编造内部数据。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Midtraining 是预训练与后训练之间的课程阶段：更高质量或补短板的数据、常伴学习率退火，可选延长上下文。</li><li>OLMo 2：约 5%–10% FLOPs、Dolmino Mix、micro-annealing 选源。</li><li>Phi-4：4K→16K、约 250B token、30% 长 / 70% 回放、RoPE 250K、LR 降 10×。</li><li>与纯退火、与领域续训、与 SFT 都可区分；报告应拆数据、LR、窗口、FLOPs。</li><li>天然长数据优于假拼接；短回放防止遗忘。</li><li>出处：OLMo 2，arXiv:2501.00656；Phi-4，arXiv:2412.08905。</li></ul>',10))])}const L=A(p,[["render",m]]);export{T as __pageData,L as default};
